using System;using System.IO;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 void ScrollTest(){var checks=new List<string>();try{timer.Stop();var viewport=home.Controls.OfType<Panel>().Single();var content=viewport.Controls.OfType<FlowLayoutPanel>().Single();var recover=content.Controls.OfType<Button>().Single(b=>b.Text.StartsWith("Recover a previous"));foreach(var size in new[]{new Size(1040,760),new Size(1280,800),new Size(1480,980)}){ClientSize=size;viewport.AutoScrollPosition=Point.Empty;PerformLayout();Application.DoEvents();viewport.AutoScrollPosition=new Point(0,Int32.MaxValue);Application.DoEvents();var bounds=viewport.RectangleToClient(recover.RectangleToScreen(recover.ClientRectangle));using(var capture=new Bitmap(Width,Height)){DrawToBitmap(capture,new Rectangle(0,0,Width,Height));capture.Save(Path.Combine(WorkspaceProgram.Test,"bottom-"+size.Width+".png"));}if(bounds.Top<0||bounds.Bottom>viewport.ClientSize.Height)throw new Exception("Recovery is clipped at "+size+": "+bounds+" in "+viewport.ClientSize+", scroll="+viewport.AutoScrollPosition+", max="+viewport.VerticalScroll.Maximum);checks.Add("Recovery button fully reachable at "+size.Width+" x "+size.Height);var grid=content.Controls.OfType<FlowLayoutPanel>().First();foreach(Control card in grid.Controls){if(card.Bottom>grid.ClientSize.Height)throw new Exception("Studio card clipped: "+card.Text); }checks.Add("All studio cards fit at "+size.Width+" x "+size.Height);}Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=true,checks}));}catch(Exception e){Atomic(Path.Combine(WorkspaceProgram.Test,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks}));}allowClose=true;Close();}
}
